        #region Mutagen
        public IEnumerable<IFormLinkGetter> EnumerateFormLinks(ISceneGetter obj, bool iterateNestedRecords = true)
        {
            foreach (var item in base.EnumerateFormLinks(obj, iterateNestedRecords))
            {
                yield return item;
            }
            if (obj.VirtualMachineAdapter is IFormLinkContainerGetter VirtualMachineAdapterlinkCont)
            {
                foreach (var item in VirtualMachineAdapterlinkCont.EnumerateFormLinks(iterateNestedRecords))
                {
                    yield return item;
                }
            }
            foreach (var item in obj.Phases.SelectMany(f => f.EnumerateFormLinks(iterateNestedRecords)))
            {
                yield return FormLinkInformation.Factory(item);
            }
            if (obj.Actions is {} ActionsItem)
            {
                foreach (var item in ActionsItem.WhereCastable<IASceneActionGetter, IFormLinkContainerGetter>()
                    .SelectMany((f) => f.EnumerateFormLinks(iterateNestedRecords)))
                {
                    yield return FormLinkInformation.Factory(item);
                }
            }
            if (FormLinkInformation.TryFactory(obj.Quest, out var QuestInfo))
            {
                yield return QuestInfo;
            }
            foreach (var item in obj.Conditions.SelectMany(f => f.EnumerateFormLinks(iterateNestedRecords)))
            {
                yield return FormLinkInformation.Factory(item);
            }
            if (FormLinkInformation.TryFactory(obj.Template, out var TemplateInfo))
            {
                yield return TemplateInfo;
            }
            if (FormLinkInformation.TryFactory(obj.SCPP, out var SCPPInfo))
            {
                yield return SCPPInfo;
            }
            if (obj.MandatoryNextChallenges is {} MandatoryNextChallengesItem)
            {
                foreach (var item in MandatoryNextChallengesItem)
                {
                    yield return FormLinkInformation.Factory(item);
                }
            }
            if (obj.ExcludedChallenges is {} ExcludedChallengesItem)
            {
                foreach (var item in ExcludedChallengesItem)
                {
                    yield return FormLinkInformation.Factory(item);
                }
            }
            if (obj.ChallengeAndKeywords is {} ChallengeAndKeywordsItem)
            {
                foreach (var item in ChallengeAndKeywordsItem)
                {
                    yield return FormLinkInformation.Factory(item);
                }
            }
            if (obj.ChallengePerks is {} ChallengePerksItem)
            {
                foreach (var item in ChallengePerksItem)
                {
                    yield return FormLinkInformation.Factory(item);
                }
            }
            if (obj.ChallengeOrKeywords is {} ChallengeOrKeywordsItem)
            {
                foreach (var item in ChallengeOrKeywordsItem)
                {
                    yield return FormLinkInformation.Factory(item);
                }
            }
            yield break;
        }
        
